/// One item of a room visual string (one JSON line), as written by `RoomVisual` (`t`: `l` line, `c` circle, `r` rect, `p` poly, `t` text). Coordinates are room tiles and may be fractional. The game does not validate drawing arguments, and `RoomVisual.import` appends arbitrary text, so lines of other shapes are possible.
#[derive(Clone, Debug, PartialEq, Serialize)]
#[serde(untagged)]
pub enum RoomVisualItem {
    /// `t` is `l`.
    Line(RoomVisualItemLine),
    /// `t` is `c`.
    Circle(RoomVisualItemCircle),
    /// `t` is `r`.
    Rect(RoomVisualItemRect),
    /// `t` is `p`.
    Poly(RoomVisualItemPoly),
    /// `t` is `t`.
    Text(RoomVisualItemText),
}

impl<'de> Deserialize<'de> for RoomVisualItem {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        // `t` may follow the other properties, so the object is buffered before the member
        // it selects is known.
        let object = serde_json::Map::<String, serde_json::Value>::deserialize(deserializer)?;
        let member = match object.get("t").and_then(serde_json::Value::as_str) {
            Some("l") => 0,
            Some("c") => 1,
            Some("r") => 2,
            Some("p") => 3,
            Some("t") => 4,
            Some(other) => {
                return Err(serde::de::Error::unknown_variant(
                    other,
                    &["l", "c", "r", "p", "t"],
                ));
            }
            None => return Err(serde::de::Error::missing_field("t")),
        };
        let object = serde_json::Value::Object(object);
        match member {
            0 => RoomVisualItemLine::deserialize(object).map(Self::Line),
            1 => RoomVisualItemCircle::deserialize(object).map(Self::Circle),
            2 => RoomVisualItemRect::deserialize(object).map(Self::Rect),
            3 => RoomVisualItemPoly::deserialize(object).map(Self::Poly),
            _ => RoomVisualItemText::deserialize(object).map(Self::Text),
        }
        .map_err(serde::de::Error::custom)
    }
}

impl RoomVisualItem {
    /// Item kind.
    #[must_use]
    pub fn kind(&self) -> &str {
        match self {
            Self::Line(member) => &member.t,
            Self::Circle(member) => &member.t,
            Self::Rect(member) => &member.t,
            Self::Poly(member) => &member.t,
            Self::Text(member) => &member.t,
        }
    }
}

